body:
I have no idea what's going on so I'll post what I have to get scons to compile. This is breaking everything so I'll pause for now.

Maybe my version of nir doesn't have `dxil_spirv_metadata`.


```patch
diff --git a/drivers/d3d12/rendering_shader_container_d3d12.cpp b/drivers/d3d12/rendering_shader_container_d3d12.cpp
index df96f4f8b11..4a1b454a55f 100644
--- a/drivers/d3d12/rendering_shader_container_d3d12.cpp
+++ b/drivers/d3d12/rendering_shader_container_d3d12.cpp
@@ -365,8 +365,6 @@ bool RenderingShaderContainerD3D12::_convert_spirv_to_nir(Span<ReflectShaderStag
 	dxil_spirv_runtime_conf dxil_runtime_conf = {};
 	dxil_runtime_conf.runtime_data_cbv.base_shader_register = RUNTIME_DATA_REGISTER;
 	dxil_runtime_conf.push_constant_cbv.base_shader_register = ROOT_CONSTANT_REGISTER;
-	dxil_runtime_conf.first_vertex_and_base_instance_mode = DXIL_SPIRV_SYSVAL_TYPE_ZERO;
-	dxil_runtime_conf.workgroup_id_mode = DXIL_SPIRV_SYSVAL_TYPE_ZERO;

 	// Explicitly keeping these false because converting UAV descriptors to SRVs do not seem to have real performance benefits on desktop GPUs.
 	// It also makes it easier to implement descriptor heaps and enhanced barriers.
@@ -381,23 +379,38 @@ bool RenderingShaderContainerD3D12::_convert_spirv_to_nir(Span<ReflectShaderStag
 		r_stages_processed.set_flag(stage_flag);

 		const char *entry_point = "main";
-		static const mesa_shader_stage SPIRV_TO_MESA_STAGES[RenderingDeviceCommons::SHADER_STAGE_MAX] = {
-			MESA_SHADER_VERTEX, // SHADER_STAGE_VERTEX
-			MESA_SHADER_FRAGMENT, // SHADER_STAGE_FRAGMENT
-			MESA_SHADER_TESS_CTRL, // SHADER_STAGE_TESSELATION_CONTROL
-			MESA_SHADER_TESS_EVAL, // SHADER_STAGE_TESSELATION_EVALUATION
-			MESA_SHADER_COMPUTE, // SHADER_STAGE_COMPUTE
-		};
+		// Map Godot shader stages to Mesa shader stages
+		gl_shader_stage mesa_stage;
+		switch (stage) {
+			case RenderingDeviceCommons::SHADER_STAGE_VERTEX:
+				mesa_stage = MESA_SHADER_VERTEX;
+				break;
+			case RenderingDeviceCommons::SHADER_STAGE_FRAGMENT:
+				mesa_stage = MESA_SHADER_FRAGMENT;
+				break;
+			case RenderingDeviceCommons::SHADER_STAGE_TESSELATION_CONTROL:
+				mesa_stage = MESA_SHADER_TESS_CTRL;
+				break;
+			case RenderingDeviceCommons::SHADER_STAGE_TESSELATION_EVALUATION:
+				mesa_stage = MESA_SHADER_TESS_EVAL;
+				break;
+			case RenderingDeviceCommons::SHADER_STAGE_COMPUTE:
+				mesa_stage = MESA_SHADER_COMPUTE;
+				break;
+			default:
+				ERR_FAIL_V_MSG(false, "Unknown shader stage");
+		}

 		Span<uint32_t> code = p_spirv[i].spirv();
+		const spirv_to_nir_options *spirv_options = dxil_spirv_nir_get_spirv_options();
 		nir_shader *shader = spirv_to_nir(
 				code.ptr(),
 				code.size(),
-				nullptr,
-				0,
-				SPIRV_TO_MESA_STAGES[stage],
+				nullptr, // specializations
+				0, // num_specializations
+				mesa_stage,
 				entry_point,
-				dxil_spirv_nir_get_spirv_options(),
+				spirv_options,
 				p_compiler_options);

 		ERR_FAIL_NULL_V_MSG(shader, false, "Shader translation (step 1) at stage " + String(RenderingDeviceCommons::SHADER_STAGE_NAMES[stage]) + " failed.");
@@ -411,8 +424,8 @@ bool RenderingShaderContainerD3D12::_convert_spirv_to_nir(Span<ReflectShaderStag
 		}

 		dxil_spirv_nir_prep(shader);
-		dxil_spirv_metadata dxil_metadata = {};
-		dxil_spirv_nir_passes(shader, &dxil_runtime_conf, &dxil_metadata);
+		bool dxil_has_metadata = false;
+		dxil_spirv_nir_passes(shader, &dxil_runtime_conf, &dxil_has_metadata);

 		r_stages_nir_shaders[stage] = shader;
 	}
@@ -451,8 +464,8 @@ bool RenderingShaderContainerD3D12::_convert_spirv_to_nir(Span<ReflectShaderStag
 			}
 		}
 		if (prev_shader) {
-			dxil_spirv_metadata dxil_metadata = {};
-			dxil_spirv_nir_link(shader, prev_shader, &dxil_runtime_conf, &dxil_metadata);
+			bool dxil_has_metadata = false;
+			dxil_spirv_nir_link(shader, prev_shader, &dxil_runtime_conf, &dxil_has_metadata);
 		}
 	}

@@ -526,8 +539,8 @@ bool RenderingShaderContainerD3D12::_convert_spirv_to_dxil(Span<ReflectShaderSta

 	// This structure must live as long as the shaders are alive.
 	nir_shader_compiler_options compiler_options = {};
-	const unsigned supported_bit_sizes = 16 | 32 | 64;
-	dxil_get_nir_compiler_options(&compiler_options, shader_model_d3d_to_dxil(D3D_SHADER_MODEL(REQUIRED_SHADER_MODEL)), supported_bit_sizes, supported_bit_sizes);
+	// Initialize compiler options manually since dxil_get_nir_compiler_options signature changed
+	// Zero-initialization with {} sets all fields to safe defaults (0, false, nullptr)
 	compiler_options.lower_base_vertex = false;

 	// This is based on spirv2dxil.c. May need updates when it changes.
```
